    static func getContract(for pick: Int) -> RookieContract? {
        return contracts[pick]
    }
    
    static func getCurrentYearSalary(pick: Int, contractYear: Int) -> Int {
        guard let contract = contracts[pick] else { return 0 }
        switch contractYear {
        case 1: return contract.year1
        case 2: return contract.year2
        case 3: return contract.year3
        case 4: return contract.year4
        default: return 0
        }
    }
